def solve(n):
    def get_next(state):
        k = sum(state)
        if k == 0:
            return None
        # k is the number of heads, flip the k-th coin (1-indexed)
        new_state = list(state)
        new_state[k-1] = 1 - new_state[k-1]
        return tuple(new_state)

    total_turns = 0
    for i in range(1 << n):
        state = tuple(1 if (i >> j) & 1 else 0 for j in range(n))
        turns = 0
        current_state = state
        while True:
            next_state = get_next(current_state)
            if next_state is None:
                break
            current_state = next_state
            turns += 1
        total_turns += turns
    return total_turns

for n in range(1, 8):
    print(f"n={n}, sum={solve(n)}")
